    total_mass = 0.0
    for sample in samples:
        cleaned = clean_sample(sample)
        if cleaned == "invalid":
            return "invalid"
        adj_conc = cleaned["conc"] * dilution
        mass = adj_conc * cleaned["vol"]
        normalized_samples.append({
            "id": cleaned["id"],
            "adj_conc": adj_conc,
            "mass": mass,
            "flag": cleaned["flag"],
            "group": cleaned["group"]
        })
        total_mass += mass
    return {"samples": normalized_samples, "total_mass": total_mass}


